// XQL Chrome Extension — generated by xiaoqinli
'use strict';

function _xql_out(s) {
    var el = document.getElementById('output');
    if (el) el.textContent += s;
}

function _xql_str(v) {
    if (v === null || v === undefined) return 'null';
    if (Array.isArray(v)) return '[' + v.map(_xql_str).join(', ') + ']';
    if (typeof v === 'object' && typeof v.toString === 'function' && v.toString !== Object.prototype.toString) return v.toString();
    if (typeof v === 'object') return JSON.stringify(v);
    return String(v);
}

function _xql_print(v) {
    var s = _xql_str(v);
    _xql_out(s + '\n');
    console.log(v);
}

function _xql_printf(fmt) {
    var args = Array.prototype.slice.call(arguments, 1);
    var i = 0;
    var s = fmt.replace(/%[sdvf%]/g, function(m) { return m === '%%' ? '%' : (i < args.length ? _xql_str(args[i++]) : m); });
    _xql_out(s);
    console.log(s);
}

class QueryInfo {
    constructor(active, currentWindow) {
        this.active = active;
        this.currentWindow = currentWindow;
    }
    toString() { return "QueryInfo(" + _xql_str(this.active) + ", " + _xql_str(this.currentWindow) + ")"; }
}

class FetchHeaders {
    constructor(accept) {
        this.accept = accept;
    }
    toString() { return "FetchHeaders(" + _xql_str(this.accept) + ")"; }
}

class FetchOptions {
    constructor(headers) {
        this.headers = headers;
    }
    toString() { return "FetchOptions(" + _xql_str(this.headers) + ")"; }
}

function getHostname(url) {
    try {
        return new URL(url).hostname;
    } catch (e) {
        return "unknown";
    }
}

function fetchDnsInfo(domain) {
    const queryUrl = (("https://cloudflare-dns.com/dns-query?name=" + domain) + "&type=A");
    const opts = new FetchOptions(new FetchHeaders("application/dns-json"));
    const t0 = Date.now();
    const p = fetch(queryUrl, opts);
    p.then(function(res) {
        const p2 = res.json();
        p2.then(function(data) {
            const t1 = Date.now();
            const latency = (t1 - t0);
            _xql_printf("\n--- DNS 与 延迟分析 ---\n");
            _xql_printf("目标域名: %s\n", domain);
            _xql_printf("解析 DNS + 往返延迟: %s ms\n", latency);
            const answer = data.Answer;
            if (answer) {
                const first = answer[0];
                _xql_printf("DNS A记录解析 IP: %s\n", first.data);
            } else {
                _xql_print("未检测到 DNS A记录解析。");
            }
        });
    });
}

document.addEventListener('DOMContentLoaded', function() {
    try {
        _xql_print("=== 网页与网络信息诊断工具 ===");
        _xql_print("正在获取数据，请稍候...");
        chrome.tabs.query(new QueryInfo(true, true), function(tabs) {
            const tab = tabs[0];
            _xql_printf("当前网页标题: %s\n", tab.title);
            _xql_printf("当前网页链接: %s\n", tab.url);
            const conn = navigator.connection;
            _xql_printf("\n--- 网络连接状态 ---\n");
            _xql_printf("物理连接类型: %s\n", conn.type);
            _xql_printf("网络传输级别: %s\n", conn.effectiveType);
            _xql_printf("下行带宽估算: %s Mb/s\n", conn.downlink);
            _xql_printf("往返延迟估算 (RTT): %s ms\n", conn.rtt);
            const hostname = getHostname(tab.url);
            fetchDnsInfo(hostname);
        });
    } catch (_err) {
        _xql_print('Error: ' + _err.message);
    }
});
